def {fn}_load(path):
    """Load a record file and return parsed lines."""
    with open(path, encoding="utf-8") as handle:
        return [line.rstrip("\n") for line in handle if line.strip()]
def {fn}_dedupe(values):
    """Keep the first occurrence of each value."""
    seen = set()
    result = []
    for value in values:
        if value not in seen:
            seen.add(value)
            result.append(value)
    return result
def {fn}_score(text, terms):
    """Return a simple overlap score for a passage."""
    tokens = text.casefold().split()
    hits = sum(1 for term in terms if term in tokens)
    return hits / max(1, len(terms))

pub fn {fn}_normalize(input: &str) -> String {
    input
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .to_lowercase()
}
pub fn {fn}_checksum(data: &[u8]) -> u64 {
    let mut value: u64 = 0;
    for byte in data {
        value = value.wrapping_mul(131).wrapping_add(u64::from(*byte));
    }
    value
}
pub fn {fn}_split(text: &str, width: usize) -> Vec<String> {
    let mut out = Vec::new();
    let mut current = String::new();
    for word in text.split_whitespace() {
        if !current.is_empty() && current.len() + 1 + word.len() > width {
            out.push(current);
            current = String::new();
        }
        if !current.is_empty() {
            current.push(' ');
        }
        current.push_str(word);
    }
    if !current.is_empty() {
        out.push(current);
    }
    out
}

export function {fn}Normalize(value) {
  return value.split(/\s+/).filter(Boolean).join(" ").toLowerCase();
}
export function {fn}Unique(values) {
  const seen = new Set();
  const result = [];
  for (const value of values) {
    if (!seen.has(value)) {
      seen.add(value);
      result.push(value);
    }
  }
  return result;
}
export function {fn}Percent(part, total) {
  if (total <= 0) {
    return 0;
  }
  return Math.round((part / total) * 1000) / 10;
}

export interface {class_name}Record {
  id: string;
  path: string;
  size: number;
}
export function {fn}SortRecords(records: {class_name}Record[]): {class_name}Record[] {
  return [...records].sort((left, right) => left.path.localeCompare(right.path));
}
export function {fn}Filter(records: {class_name}Record[], minimum: number): {class_name}Record[] {
  return records.filter((record) => record.size >= minimum);
}

